def countGeometricTriplets(nums, ratio):
    one = {}
    two = {}
    ans = 0
    for x in nums:
        if x % ratio == 0:
            y = x // ratio
            ans += two.get(y, 0)
            if y in one:
                two[x] = two.get(x, 0) + one[y]
        one[x] = one.get(x, 0) + 1
    return ans % 1000000007
